const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const state={page:'overview',services:[{id:'app',name:'Web App',desc:'Next.js · localhost:3000',version:'v0.8.4',port:3000,running:true,icon:'cube',color:''},{id:'api',name:'API Server',desc:'Node.js · localhost:4000',version:'v0.8.4',port:4000,running:true,icon:'terminal',color:'blue'},{id:'worker',name:'Background Worker',desc:'Queue processor · 2 jobs',version:'v0.8.3',port:null,running:false,icon:'activity',color:'green'}],tests:[{name:'Login und Session',suite:'E2E',duration:'2.4s',status:'success'},{name:'API Antwortzeiten',suite:'Performance',duration:'1.8s',status:'success'},{name:'Datenimport',suite:'Integration',duration:'0.9s',status:'success'},{name:'Export großer Datenmengen',suite:'Performance',duration:'—',status:'pending'}],issues:[{id:'PV-42',title:'Onboarding-Flow für neue Nutzer',type:'Feature',status:'In Arbeit',source:'GitHub',done:false},{id:'PV-38',title:'Antwortzeiten unter 200 ms halten',type:'Performance',status:'Offen',source:'Linear',done:false},{id:'PV-35',title:'Dateivorschau für JSON ergänzen',type:'Feature',status:'Offen',source:'GitHub',done:false},{id:'PV-29',title:'Fehler bei leerer Warteliste',type:'Bug',status:'Erledigt',source:'Linear',done:true}],metric:'Latenz',dataTab:'struktur',file:'.projectroom/project.yaml',spec:'vision',runningTests:false};
const labels={overview:'Übersicht',spec:'Spezifikation',runtime:'Laufzeit',tests:'Tests',data:'Daten',files:'Dateien',issues:'Aufgaben',activity:'Aktivität'};
const head=(title,sub,actions='')=>`<div class="page-head"><div><div class="eyebrow">Blackbox Agent B / Project Room</div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`;
const btn=(label,action,kind='')=>`<button class="btn ${kind}" data-action="${action}">${label}</button>`;
const badge=(text,kind='')=>`<span class="badge ${kind}"><span class="dot"></span>${text}</span>`;
function serviceRow(s){return `<div class="env-row"><div class="service-icon ${s.color}">${icon(s.icon)}</div><div class="service-meta"><div class="service-title">${s.name} ${badge(s.running?'Läuft':'Gestoppt',s.running?'':'off')}</div><div class="service-sub">${s.desc} <span style="color:#c5cbd4">·</span> ${s.version}</div></div><div class="service-right"><span class="service-port">${s.port?':'+s.port:''}</span>${s.running&&s.port?`<button class="mini-btn" data-action="preview" title="Vorschau öffnen">${icon('external')}</button>`:''}<button class="mini-btn" data-action="service:${s.id}" title="${s.running?'Stoppen':'Starten'}">${icon(s.running?'stop':'play')}</button></div></div>`}
const chartPath={Latenz:'M0 68 C25 66 34 48 54 53 S80 62 101 42 S138 65 163 51 S201 27 224 35 S258 56 282 42 S315 19 338 34 S371 47 395 25 S434 50 455 36 S486 48 510 27 S547 46 570 27 S604 37 630 18',CPU:'M0 62 C32 55 44 66 67 46 S100 29 129 48 S161 69 190 44 S224 56 254 38 S292 62 319 46 S346 28 371 42 S407 59 440 38 S475 58 507 44 S542 30 570 42 S604 54 630 34',Speicher:'M0 78 C45 78 48 71 88 70 S135 63 165 62 S220 54 258 56 S290 48 322 49 S370 42 413 40 S452 35 488 34 S536 28 570 26 S608 22 630 19'};
function chart(){return `<div class="metric-wrap"><div class="metric-tabs">${['Latenz','CPU','Speicher'].map(m=>`<button class="${state.metric===m?'active':''}" data-action="metric:${m}">${m}</button>`).join('')}</div><div class="chart"><svg viewBox="0 0 630 100" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9c8bee" stop-opacity=".22"/><stop offset="1" stop-color="#9c8bee" stop-opacity="0"/></linearGradient></defs><path d="${chartPath[state.metric]} L630 100 L0 100Z" fill="url(#fill)"/><path d="${chartPath[state.metric]}" stroke="#8671e1" stroke-width="2.4" fill="none"/></svg></div><div class="chart-labels"><span>09:00</span><span>10:00</span><span>11:00</span><span>12:00</span><span>13:00</span><span>Jetzt</span></div></div><div class="metric-summary"><div><span>Ø Latenz</span><strong>142 ms</strong></div><div><span>CPU</span><strong>18.6 %</strong></div><div><span>Speicher</span><strong>384 MB</strong></div></div>`}
function overview(){return `${head('Alles im Blick.','Entwicklung, Qualität und Produktfortschritt an einem Ort.',`${btn(icon('play')+' Alle Tests starten','run-tests','primary')}`)}<div class="grid summary-grid"><div class="card stat-card"><div class="stat-top">Laufende Dienste · Demo ${icon('play')}</div><div class="stat-number">${state.services.filter(s=>s.running).length} <span style="font-size:15px;color:#aab3bf;font-weight:500">/ ${state.services.length}</span></div><div class="stat-foot"><span class="good">● System bereit</span> · lokal</div></div><div class="card stat-card"><div class="stat-top">Letzte Tests ${icon('flask')}</div><div class="stat-number">${state.tests.filter(t=>t.status==='success').length}<span style="color:#b2bcc8">/${state.tests.length}</span></div><div class="stat-foot"><span class="good">↑ 2 mehr</span> als letzter Lauf</div></div><div class="card stat-card"><div class="stat-top">Offene Aufgaben ${icon('list')}</div><div class="stat-number">${state.issues.filter(i=>!i.done).length.toString().padStart(2,'0')}</div><div class="stat-foot">GitHub <span style="color:#c5cad3">·</span> Linear Demo</div></div><div class="card stat-card"><div class="stat-top">P95 Antwortzeit ${icon('activity')}</div><div class="stat-number">186 <span style="font-size:15px;color:#aab3bf">ms</span></div><div class="stat-foot"><span class="good">↓ 12 %</span> in 24 Stunden</div></div></div><div class="grid two-col"><div class="stack"><section class="card"><div class="card-head"><div><h2>Entwicklungsumgebung</h2><p>Dienste und Versionen dieses Projekts</p></div><button class="link" data-page="runtime">Alle Dienste ${icon('arrow')}</button></div>${state.services.map(serviceRow).join('')}</section><section class="card"><div class="card-head"><div><h2>Performance</h2><p>Lokale Umgebung · letzte 4 Stunden</p></div><button class="link" data-page="activity">Details ${icon('arrow')}</button></div>${chart()}</section></div><div class="stack"><section class="card"><div class="card-head"><div><h2>Nächste Aufgaben</h2><p>GitHub und Linear · Beispielaufgaben</p></div><button class="link" data-page="issues">Alle Aufgaben ${icon('arrow')}</button></div>${state.issues.slice(0,3).map(i=>`<div class="queue-item"><button class="task-check ${i.done?'done':''}" data-action="issue:${i.id}" aria-label="Aufgabe umschalten">${i.done?icon('check'):''}</button><div class="queue-copy"><strong>${i.title}</strong><small>${i.id} · ${i.source}</small></div><span class="tag ${i.type==='Performance'?'orange':''}">${i.type}</span></div>`).join('')}</section><section class="card"><div class="card-head"><div><h2>Testabdeckung</h2><p>Letzter Lauf · heute 13:42</p></div><button class="link" data-page="tests">Tests ansehen ${icon('arrow')}</button></div><div class="test-progress"><div class="progress-head"><strong>87 %</strong><span>26 von 30 Checks bestanden</span></div><div class="progress-track"><div class="progress-fill"></div></div><div class="progress-foot"><div class="legend"><span><i></i> Bestanden</span><span><i></i> Ausstehend</span></div><span>+4 % diese Woche</span></div></div><div class="test-latest">${icon('check')} Letzter Lauf <strong>erfolgreich</strong> · 1 min 24 s</div></section><section class="card spec-card"><div class="spec-symbol">${icon('doc')}</div><div><h2>Die Produktidee bleibt sichtbar</h2><p>Vision, Anforderungen und Entscheidungen liegen neben Code und Tests – für alle im Repository.</p><button data-page="spec">Spezifikation öffnen →</button></div></section></div></div><div class="footer-note">${icon('clock')} Prototyp mit Beispieldaten · Zustandsänderungen gelten nur in dieser Sitzung</div>`}
function runtime(){return `${head('Laufzeit','Apps starten, stoppen und ihre lokale Vorschau öffnen.',`${btn(icon('play')+' Alle starten','start-all','primary')}`)}<section class="card"><div class="card-head"><div><h2>Dienste</h2><p>Definiert in .projectroom/project.yaml · gewünschter Zustand wird lokal gestartet</p></div>${badge(state.services.filter(s=>s.running).length+' von 3 laufen')}</div>${state.services.map(serviceRow).join('')}</section><div class="grid summary-grid" style="margin-top:18px"><div class="card stat-card"><div class="stat-top">Aktive Version ${icon('git')}</div><div class="stat-number" style="font-size:22px">v0.8.4</div><div class="stat-foot">Branch main · commit 8a42c1f</div></div><div class="card stat-card"><div class="stat-top">Umgebung ${icon('terminal')}</div><div class="stat-number" style="font-size:22px">Lokal</div><div class="stat-foot">3 Prozesse definiert</div></div><div class="card stat-card"><div class="stat-top">Restart-Zähler ${icon('activity')}</div><div class="stat-number">0</div><div class="stat-foot">Letzte 24 Stunden</div></div><div class="card stat-card"><div class="stat-top">Health Checks ${icon('check')}</div><div class="stat-number">2/2</div><div class="stat-foot"><span class="good">Alle erreichbar</span></div></div></div><section class="card"><div class="card-head"><div><h2>Protokoll</h2><p>Beispielhafte Konsolenausgabe für den ausgewählten Workspace</p></div></div><pre style="margin:0;padding:20px;background:#172033;color:#b7c7df;font:11px/1.9 ui-monospace,monospace;overflow:auto;border-radius:0 0 12px 12px"><span style="color:#62cf9c">13:42:08</span>  [web]     ready on http://localhost:3000\n<span style="color:#62cf9c">13:42:09</span>  [api]     listening on :4000\n<span style="color:#62cf9c">13:42:10</span>  [health]  all checks passed\n<span style="color:#d6a6ef">13:43:01</span>  [worker]  waiting to start</pre></section>`}
function tests(){return `${head('Tests & Qualität','Sammlungen ausführen und neue Prüfungen im Projekt definieren.',`${btn(icon('plus')+' Test hinzufügen','add-test')}${btn(icon('play')+' Tests ausführen','run-tests','primary')}`)}<div class="grid summary-grid"><div class="card stat-card"><div class="stat-top">Bestanden ${icon('check')}</div><div class="stat-number">${state.tests.filter(t=>t.status==='success').length}</div><div class="stat-foot"><span class="good">Letzter Lauf erfolgreich</span></div></div><div class="card stat-card"><div class="stat-top">Ausstehend ${icon('clock')}</div><div class="stat-number">${state.tests.filter(t=>t.status==='pending').length}</div><div class="stat-foot">Warten auf nächsten Lauf</div></div><div class="card stat-card"><div class="stat-top">Laufzeit ${icon('activity')}</div><div class="stat-number">1:24</div><div class="stat-foot">Minuten · letzter Lauf</div></div><div class="card stat-card"><div class="stat-top">Abdeckung ${icon('flask')}</div><div class="stat-number">87%</div><div class="stat-foot"><span class="good">↑ 4 %</span> diese Woche</div></div></div><section class="card"><div class="card-head"><div><h2>Testsammlung</h2><p>Prüfungen werden mit dem Projekt versioniert</p></div></div><div class="section-toolbar" style="padding:16px 19px 0;margin:0"><div class="search">${icon('search')}<input id="testSearch" placeholder="Tests suchen…" aria-label="Tests suchen"></div></div><div id="testTable">${testTable()}</div></section>`}
function testTable(q=''){let rows=state.tests.filter(t=>t.name.toLowerCase().includes(q.toLowerCase())||t.suite.toLowerCase().includes(q.toLowerCase()));return rows.length?`<table class="table"><thead><tr><th>Test</th><th>Sammlung</th><th>Letzter Lauf</th><th>Status</th><th></th></tr></thead><tbody>${rows.map((t,i)=>`<tr><td><strong>${escapeHtml(t.name)}</strong></td><td>${escapeHtml(t.suite)}</td><td>${t.duration}</td><td>${badge(t.status==='success'?'Bestanden':t.status==='running'?'Läuft':'Ausstehend',t.status==='success'?'':t.status==='running'?'warn':'off')}</td><td><button class="mini-btn" data-action="single-test:${state.tests.indexOf(t)}" title="Test starten">${icon('play')}</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty">Keine passenden Tests gefunden.</div>`}
const docs={vision:{title:'Produktvision',label:'01 / Vision',text:'Eine gemeinsame Arbeitsumgebung, in der Produktidee, Entwicklung und Betrieb sichtbar zusammenkommen. Jeder, der das Repository öffnet, versteht den Produktzustand und kann die definierte Umgebung starten.',points:['Spezifikation und Entscheidungen liegen versioniert im Repository.','Dienste, Tests und Datenquellen werden in einer lesbaren Projektdatei beschrieben.','Der Viewer visualisiert den tatsächlichen Zustand und macht nächste Schritte klar.']},requirements:{title:'Anforderungen',label:'02 / Anforderungen',text:'Der Project Room bündelt bestehende Werkzeuge. Er schafft einen klaren Einstiegspunkt für Produktmanager und Entwickler.',points:['Dienste starten, stoppen und auf Vorschauen zugreifen.','Tests ausführen und ihre Historie nachvollziehen.','Performance und Ressourcenverbrauch beobachten.','GitHub- und Linear-Aufgaben gemeinsam anzeigen.','Datenstrukturen und Dateien erkunden.']},decisions:{title:'Entscheidungen',label:'03 / Entscheidungen',text:'Die Projektkonfiguration ist Teil des Repositories und beschreibt Komponenten, Befehle, Ports, Health Checks und Integrationen.',points:['.projectroom/project.yaml als menschenlesbarer Einstiegspunkt.','Adapter für vorhandene Tools statt eigene Test- oder Datenbank-Engines.','Lokale Desktop-App als langfristige Laufzeitumgebung.']}};
function spec(){let d=docs[state.spec];return `${head('Spezifikation','Produktidee, Anforderungen und Entscheidungen direkt beim Code.',`${btn(icon('external')+' Repository','repo')}`)}<div class="spec-layout"><div class="card spec-list">${Object.entries(docs).map(([k,v])=>`<button data-action="spec:${k}" class="${state.spec===k?'active':''}">${v.title}</button>`).join('')}<div style="border-top:1px solid var(--line);margin:10px 9px;padding:16px 4px 6px;color:#a0a9b6;font-size:10px">Versioniert mit dem Repository<br><b style="color:#677384">main · v0.8.4</b></div></div><article class="card doc"><div class="label">${d.label}</div><h2>${d.title}</h2><p>${d.text}</p><div class="doc-callout">Diese Ansicht zeigt, wie eine Spec-Kit-Struktur mit dem laufenden Produkt verbunden sein könnte.</div><h3>Leitlinien</h3><ul>${d.points.map(p=>`<li>${p}</li>`).join('')}</ul><h3>Im Repository</h3><p><code>specs/${state.spec}.md</code> · Zuletzt geändert vor 2 Tagen</p></article></div>`}
function data(){return `${head('Daten & Strukturen','Datenbanken und Projektverzeichnisse schnell finden und erkunden.',`${btn(icon('external')+' Viewer öffnen','data-viewer','primary')}`)}<div class="grid summary-grid"><div class="card stat-card"><div class="stat-top">Datenbank ${icon('database')}</div><div class="stat-number" style="font-size:21px">PostgreSQL</div><div class="stat-foot">Beispieldaten · lokal</div></div><div class="card stat-card"><div class="stat-top">Tabellen ${icon('grid')}</div><div class="stat-number">4</div><div class="stat-foot">public schema</div></div><div class="card stat-card"><div class="stat-top">Datensätze ${icon('list')}</div><div class="stat-number">1.248</div><div class="stat-foot">Beispielhafte Summe</div></div><div class="card stat-card"><div class="stat-top">Dateispeicher ${icon('folder')}</div><div class="stat-number">2.3 <span style="font-size:15px;color:#aab3bf">GB</span></div><div class="stat-foot">/data/uploads</div></div></div><section class="card"><div class="card-head"><div><h2>Datenmodell</h2><p>Übersicht der konfigurierten Strukturen</p></div></div><div class="data-tabs"><button data-action="data:struktur" class="${state.dataTab==='struktur'?'active':''}">Schema</button><button data-action="data:tabellen" class="${state.dataTab==='tabellen'?'active':''}">Tabellen</button><button data-action="data:verzeichnisse" class="${state.dataTab==='verzeichnisse'?'active':''}">Verzeichnisse</button></div>${state.dataTab==='struktur'?`<div class="diagram"><div class="data-node"><b>users</b><span>id · uuid</span><span>email · varchar</span><span>created_at · timestamp</span></div><div class="connector"></div><div class="data-node"><b>projects</b><span>id · uuid</span><span>owner_id · uuid</span><span>name · varchar</span></div><div class="connector"></div><div class="data-node"><b>runs</b><span>id · uuid</span><span>project_id · uuid</span><span>status · enum</span></div></div>`:state.dataTab==='tabellen'?`<table class="table"><thead><tr><th>Name</th><th>Zeilen</th><th>Größe</th><th></th></tr></thead><tbody>${[['users','326','112 KB'],['projects','48','56 KB'],['runs','812','368 KB'],['events','62','24 KB']].map(r=>`<tr class="clickable" data-action="table:${r[0]}"><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td><td>${icon('arrow')}</td></tr>`).join('')}</tbody></table>`:`<table class="table"><thead><tr><th>Pfad</th><th>Typ</th><th>Größe</th><th></th></tr></thead><tbody>${[['/data/uploads','Dateispeicher','2.3 GB'],['/data/exports','Exports','128 MB'],['/logs','Protokolle','42 MB']].map(r=>`<tr class="clickable" data-action="folder:${r[0]}"><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td><td>${icon('arrow')}</td></tr>`).join('')}</tbody></table>`}</section>`}
const files={'.projectroom/project.yaml':'# Project Room · Projektkonfiguration\nproject: blackbox-agent-b\nversion: 0.8.4\n\nservices:\n  web:\n    command: npm run dev\n    port: 3000\n    health: /api/health\n  api:\n    command: npm run api\n    port: 4000\n  worker:\n    command: npm run worker\n\ntests:\n  command: npm test\n  suites: [e2e, integration, performance]\n\ndata:\n  postgres: DATABASE_URL\n  files: ./data/uploads\n\nintegrations:\n  issues: [github, linear]','README.md':'# Blackbox Agent B\n\nEin Produkt mit einer versionierten Entwicklungsumgebung.\n\n## Schnellstart\n1. Repository öffnen\n2. Project Room starten\n3. Dienste und Tests im Dashboard bedienen','specs/vision.md':'# Produktvision\n\nEine gemeinsame Arbeitsumgebung für die Entwicklung professioneller Software.','src/app/page.tsx':'export default function Home() {\n  return (\n    <main>\n      <h1>Blackbox Agent B</h1>\n    </main>\n  );\n}','tests/login.spec.ts':'import { test, expect } from "@playwright/test";\n\ntest("login and session", async ({ page }) => {\n  await page.goto("/");\n  await expect(page).toHaveTitle(/Blackbox/);\n});'};
function filesPage(){let code=files[state.file]||'';return `${head('Dateien','Quelltext, Konfiguration und Änderungen im Projekt durchsuchen.',`${btn(icon('git')+' Änderungen ansehen','changes')}`)}<section class="card file-layout"><div class="file-tree"><div style="font-size:10px;color:#9da7b4;text-transform:uppercase;letter-spacing:1px;padding:4px 9px 13px;font-weight:800">Explorer</div><button data-action="file:.projectroom/project.yaml" class="${state.file==='.projectroom/project.yaml'?'active':''}">${icon('doc')} .projectroom/project.yaml</button><button data-action="file:README.md" class="${state.file==='README.md'?'active':''}">${icon('doc')} README.md</button><button>${icon('folder')} specs</button><button class="indent ${state.file==='specs/vision.md'?'active':''}" data-action="file:specs/vision.md">${icon('doc')} vision.md</button><button>${icon('folder')} src / app</button><button class="indent ${state.file==='src/app/page.tsx'?'active':''}" data-action="file:src/app/page.tsx">${icon('doc')} page.tsx</button><button>${icon('folder')} tests</button><button class="indent ${state.file==='tests/login.spec.ts'?'active':''}" data-action="file:tests/login.spec.ts">${icon('doc')} login.spec.ts</button></div><div class="code-view"><div class="code-header"><span>${state.file}</span><span>main · <span style="color:#39ad80">●</span> synchronisiert</span></div><pre>${escapeHtml(code).split('\n').map((line,i)=>`<span class="ln">${i+1}</span>${line}`).join('\n')}</pre></div></section>`}
function issues(){return `${head('Aufgaben & Warteliste','Produktarbeit aus GitHub und Linear in einer gemeinsamen Ansicht (Demo).',`${btn(icon('plus')+' Aufgabe hinzufügen','add-issue','primary')}`)}<section class="card"><div class="card-head"><div><h2>Produkt-Backlog</h2><p>${state.issues.filter(i=>!i.done).length} offene Aufgaben · Quellen: GitHub und Linear · Demo</p></div></div><table class="table"><thead><tr><th>Aufgabe</th><th>Typ</th><th>Status</th><th>Quelle</th><th></th></tr></thead><tbody>${state.issues.map(i=>`<tr><td><strong>${escapeHtml(i.title)}</strong><small>${i.id}</small></td><td><span class="tag ${i.type==='Performance'?'orange':i.type==='Bug'?'blue':''}">${i.type}</span></td><td>${badge(i.done?'Erledigt':i.status,i.done?'':'warn')}</td><td class="muted">${i.source}</td><td><button class="mini-btn" data-action="issue:${i.id}" title="Status umschalten">${icon(i.done?'play':'check')}</button></td></tr>`).join('')}</tbody></table></section><div class="footer-note">${icon('activity')} Im Prototyp sind Quellen und Synchronisierung simuliert.</div>`}
function activity(){return `${head('Aktivität','Änderungen, Testläufe und Laufzeitereignisse auf einer Zeitachse.',`${btn(icon('git')+' Repository öffnen','repo')}`)}<section class="card"><div class="card-head"><div><h2>Heute</h2><p>Produkt- und Entwicklungsereignisse</p></div></div>${[['13:42','Tests erfolgreich','26 von 30 Checks bestanden','flask'],['13:36','Web App gestartet','Version v0.8.4 auf Port 3000','play'],['12:18','Spezifikation geändert','Anforderung „Datenstrukturen öffnen“ ergänzt','doc'],['10:54','Commit auf main','8a42c1f · Testabdeckung erweitert','git'],['09:20','Neue Aufgabe','PV-42 · Onboarding-Flow für neue Nutzer','list']].map(e=>`<div class="env-row"><div class="service-icon">${icon(e[3])}</div><div class="service-meta"><div class="service-title">${e[1]}</div><div class="service-sub">${e[2]}</div></div><div class="muted" style="font-size:11px">${e[0]}</div></div>`).join('')}</section>`}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));document.getElementById('crumb').textContent=labels[state.page];document.getElementById('runningCount').textContent=state.services.filter(s=>s.running).length;document.getElementById('content').innerHTML=({overview,runtime,tests,spec,data,files:filesPage,issues,activity})[state.page]();document.title=labels[state.page]+' · Project Room'}
let toastTimer;function toast(message){let el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300)}
function modal(title,body,save){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" id="modalBack"><div class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Schließen">×</button></div><form id="modalForm"><div class="modal-body">${body}</div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Abbrechen</button><button type="submit" class="btn primary">Hinzufügen</button></div></form></div></div>`;document.getElementById('modalForm').onsubmit=e=>{e.preventDefault();save(new FormData(e.target));document.getElementById('modalRoot').innerHTML='';render()};document.querySelector('#modalForm input')?.focus()}
document.addEventListener('click',e=>{let page=e.target.closest('[data-page]');if(page){state.page=page.dataset.page;render();window.scrollTo(0,0);return}let el=e.target.closest('[data-action]');if(!el)return;let [action,arg]=el.dataset.action.split(':');if(action==='service'){let s=state.services.find(x=>x.id===arg);s.running=!s.running;render();toast(`${s.name} ${s.running?'gestartet':'gestoppt'} (Simulation)`)}else if(action==='start-all'){state.services.forEach(s=>s.running=true);render();toast('Alle Dienste gestartet (Simulation)')}else if(action==='metric'||action==='spec'||action==='data'||action==='file'){state[{metric:'metric',spec:'spec',data:'dataTab',file:'file'}[action]]=arg;render()}else if(action==='issue'){let i=state.issues.find(x=>x.id===arg);i.done=!i.done;i.status=i.done?'Erledigt':'Offen';render();toast('Aufgabenstatus lokal aktualisiert')}else if(action==='add-test'){modal('Neuen Test hinzufügen','<label for="name">Name des Tests</label><input id="name" name="name" required placeholder="z. B. Import prüfen"><label for="suite">Sammlung</label><select id="suite" name="suite"><option>E2E</option><option>Integration</option><option>Performance</option><option>Unit</option></select>',f=>{state.tests.push({name:f.get('name').trim(),suite:f.get('suite'),duration:'—',status:'pending'});toast('Test zur Sammlung hinzugefügt')})}else if(action==='add-issue'){modal('Aufgabe hinzufügen','<label for="name">Titel</label><input id="name" name="name" required placeholder="Was soll umgesetzt werden?"><label for="type">Typ</label><select id="type" name="type"><option>Feature</option><option>Bug</option><option>Performance</option></select>',f=>{state.issues.unshift({id:'PV-'+(43+state.issues.length-4),title:f.get('name').trim(),type:f.get('type'),status:'Offen',source:'Lokal',done:false});toast('Aufgabe hinzugefügt')})}else if(action==='run-tests'){state.tests.forEach(t=>t.status='running');render();toast('Tests laufen (Simulation)');setTimeout(()=>{state.tests.forEach(t=>t.status='success');render();toast('Alle Tests erfolgreich abgeschlossen')},1800)}else if(action==='single-test'){let t=state.tests[Number(arg)];t.status='running';render();toast(`${t.name} läuft (Simulation)`);setTimeout(()=>{t.status='success';render();toast(`${t.name} bestanden`)},1100)}else if(action==='close-modal'){document.getElementById('modalRoot').innerHTML=''}else if(action==='repo'){window.open('https://github.com/bventures007/blackbox-agent-b','_blank','noopener,noreferrer')}else if(action==='preview'){toast('In einer echten Desktop-App öffnet sich hier die lokale Vorschau.')}else if(action==='data-viewer'||action==='table'||action==='folder'){toast('Hier würde der konfigurierte Daten-Viewer geöffnet.')}else if(action==='changes'){toast('Hier würden Git-Diffs und ungespeicherte Änderungen erscheinen.')}});
document.addEventListener('input',e=>{if(e.target.id==='testSearch')document.getElementById('testTable').innerHTML=testTable(e.target.value)});
document.getElementById('projectPicker').onclick=()=>toast('Projektwechsel ist in diesem Prototypen noch nicht verbunden.');document.getElementById('settingsBtn').onclick=()=>toast('Projektkonfiguration liegt beispielhaft in .projectroom/project.yaml.');document.getElementById('notifications').onclick=()=>toast('Keine neuen Benachrichtigungen.');document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('modalRoot').innerHTML=''});render();
